import { expect, type Page, test } from "@playwright/test";

// These tests run in the "chromium-authenticated" project with the storage
// state generated by auth.setup.ts (dependencies: ["setup"]).

// WikiCard has no data-testid; its article links are the only anchors pointing
// at /wiki/<id> inside the home page's <main>.
const articleLinks = (page: Page) => page.locator('main a[href^="/wiki/"]');

const titleField = (page: Page) => page.locator('input[name="title"]');

// MDEditor renders a <textarea name="content"> (class w-md-editor-text-input
// is kept as a fallback in case the attribute ever changes).
const contentField = (page: Page) =>
  page.locator('textarea[name="content"], .w-md-editor-text-input').first();

// Scoped to the editor form so the account/user menu button in the navbar can
// never shadow the submit button.
const saveButton = (page: Page) =>
  page.locator('form button[type="submit"]').first();

async function createArticleViaForm(
  page: Page,
  title: string,
  content: string,
): Promise<void> {
  await page.goto("/wiki/edit/new");
  await expect(page).toHaveURL("/wiki/edit/new");

  await titleField(page).fill(title);
  await contentField(page).fill(content);
  await saveButton(page).click();

  // createArticle() returns the inserted id and the client router pushes to
  // /wiki/<id>. 30s absorbs a cold Neon connection.
  await page.waitForURL(/\/wiki\/\d+/, { timeout: 30_000 });
}

function articleIdFromUrl(page: Page): string {
  const match = page.url().match(/\/wiki\/(\d+)/);
  expect(match, `Expected an article URL, got ${page.url()}`).not.toBeNull();
  return match?.[1] ?? "0";
}

test.describe("Article CRUD Operations (Authenticated)", () => {
  test("should show New Article button when authenticated", async ({
    page,
  }) => {
    await page.goto("/");

    // Canary test: fails first when the storage state was not generated or not
    // applied, with a much clearer message than every other test in this file.
    await expect(page.getByTestId("new-article-btn")).toBeVisible();
    await expect(page.getByTestId("user-menu")).toBeVisible();
  });

  test("should display articles on home page", async ({ page }) => {
    await page.goto("/");

    await expect(page).toHaveURL("/");
    await expect(page.getByRole("link", { name: "Wikimasters" })).toBeVisible();

    // global-setup.ts seeds 3 articles, so content must be present — no
    // conditional skipping on an empty page.
    await expect(
      articleLinks(page).first(),
      "expected at least one article on the home page (global-setup seeds 3)",
    ).toBeVisible();
  });

  test("should navigate to article detail page", async ({ page }) => {
    await page.goto("/");

    const firstArticle = articleLinks(page).first();
    await expect(
      firstArticle,
      "expected at least one seeded article to open",
    ).toBeVisible();
    await firstArticle.click();

    await expect(page).toHaveURL(/\/wiki\/\d+/);

    // The detail page renders the title in an <h1> (there is no <main> there).
    await expect(page.locator("h1")).toBeVisible();
  });

  test("should create a new article", async ({ page }) => {
    const uniqueTitle = `Test Article ${Date.now()}`;
    await createArticleViaForm(
      page,
      uniqueTitle,
      "This is a test article content created by Playwright E2E test.",
    );

    await expect(
      page.locator("h1").filter({ hasText: uniqueTitle }),
    ).toBeVisible({ timeout: 15_000 });
  });

  test("should update an existing article", async ({ page }) => {
    const originalTitle = `Article to Update ${Date.now()}`;
    await createArticleViaForm(
      page,
      originalTitle,
      "Original content that will be changed",
    );

    const articleId = articleIdFromUrl(page);

    await page.goto(`/wiki/edit/${articleId}`);
    await titleField(page).waitFor({ state: "visible" });

    const updatedTitle = `Updated Article ${Date.now()}`;
    await titleField(page).fill(updatedTitle);
    await contentField(page).fill(
      "This content has been updated by Playwright test.",
    );
    await saveButton(page).click();

    await page.waitForURL(/\/wiki\/\d+/, { timeout: 30_000 });

    await expect(
      page.locator("h1").filter({ hasText: updatedTitle }),
    ).toBeVisible({ timeout: 15_000 });
  });

  test("should delete an article", async ({ page }) => {
    const uniqueTitle = `Article to Delete ${Date.now()}`;
    await createArticleViaForm(
      page,
      uniqueTitle,
      "This article will be deleted",
    );

    await expect(
      page.locator("h1").filter({ hasText: uniqueTitle }),
    ).toBeVisible();

    // Hard assertion: the seeded/test user owns the article, so the button
    // must be there. No conditional "if visible" skipping.
    const deleteButton = page
      .locator("button")
      .filter({ hasText: /Delete/i })
      .first();
    await expect(deleteButton).toBeVisible();

    // Deletion is a server-action form submit (no JS confirm dialog) that
    // redirects back to the home page.
    await deleteButton.click();
    await page.waitForURL("/", { timeout: 20_000 });
    await expect(page).toHaveURL("/");

    await expect(page.getByText(uniqueTitle)).not.toBeVisible();
  });

  test("should prevent creating article with empty title", async ({ page }) => {
    await page.goto("/wiki/edit/new");

    await contentField(page).fill("Some content");
    await saveButton(page).click();

    // Client-side validation blocks the submit and shows an explicit error.
    await expect(page.getByText("Title is required")).toBeVisible();
    await expect(page).toHaveURL("/wiki/edit/new");
  });

  test("should prevent creating article with empty content", async ({
    page,
  }) => {
    await page.goto("/wiki/edit/new");

    await titleField(page).fill("Test Title");
    await saveButton(page).click();

    await expect(page.getByText("Content is required")).toBeVisible();
    await expect(page).toHaveURL("/wiki/edit/new");
  });

  test("should display article content on detail page", async ({ page }) => {
    const uniqueTitle = `Detail Test Article ${Date.now()}`;
    const uniqueContent = "Testing detail page display with unique content.";

    await createArticleViaForm(page, uniqueTitle, uniqueContent);

    await expect(
      page.locator("h1").filter({ hasText: uniqueTitle }),
    ).toBeVisible();

    // Content is rendered from Markdown, so match on the plain sentence.
    await expect(page.getByText(uniqueContent)).toBeVisible();
  });

  test("should allow navigating between article pages", async ({ page }) => {
    await page.goto("/");

    const firstArticle = articleLinks(page).first();
    await expect(firstArticle).toBeVisible();
    await firstArticle.click();
    await expect(page).toHaveURL(/\/wiki\/\d+/);

    // The navbar logo links back to the home page on every route.
    await page.getByTestId("navbar-logo").click();
    await expect(page).toHaveURL("/");
    await expect(page.getByTestId("navbar-logo")).toBeVisible();
  });

  test("should display AI-generated summary for articles", async ({ page }) => {
    const uniqueTitle = `Summary Test ${Date.now()}`;
    await createArticleViaForm(
      page,
      uniqueTitle,
      "This is a comprehensive article about testing. It covers various aspects of E2E testing with Playwright and how to write effective tests.",
    );

    // Summaries are generated synchronously in the create action; the article
    // page must render with the title either way.
    await expect(
      page.locator("h1").filter({ hasText: uniqueTitle }),
    ).toBeVisible();
  });

  test("should allow editing own articles", async ({ page }) => {
    const uniqueTitle = `Editable Article ${Date.now()}`;
    await createArticleViaForm(page, uniqueTitle, "Original content");

    const articleId = articleIdFromUrl(page);

    await page.goto(`/wiki/edit/${articleId}`);

    // Own articles must not redirect away from the edit page.
    await expect(page).toHaveURL(`/wiki/edit/${articleId}`);

    const title = titleField(page);
    await expect(title).toBeVisible();
    await expect(title).toHaveValue(uniqueTitle);
  });
});
